BEGIN;
SET CONSTRAINTS ALL DEFERRED;
DO $$ BEGIN
    PERFORM 1 FROM public.devices WHERE slug IN ('xreal-one','xreal-one-pro','xreal-air-2-pro','xreal-air-2-ultra','xreal-air','xreal-air-2','rayneo-x2','rayneo-air-2','rayneo-air-2s','rayneo-air-3s','rayneo-air-4-pro','rayneo-x3-pro','rokid-max','rokid-air','rokid-ar-lite','rokid-glasses','viture-pro','viture-one','viture-one-lite','inmo-air-2','inmo-go3','ray-ban-meta','brilliant-labs-frame','even-realities-g1') FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.devices d JOIN (VALUES ('xreal-one','xreal','display_ar'::public.device_schema_type),
('xreal-one-pro','xreal','display_ar'::public.device_schema_type),
('xreal-air-2-pro','xreal','display_ar'::public.device_schema_type),
('xreal-air-2-ultra','xreal','display_ar'::public.device_schema_type),
('xreal-air','xreal','display_ar'::public.device_schema_type),
('xreal-air-2','xreal','display_ar'::public.device_schema_type),
('rayneo-x2','rayneo','ai_hud'::public.device_schema_type),
('rayneo-air-2','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-2s','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-3s','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-4-pro','rayneo','display_ar'::public.device_schema_type),
('rayneo-x3-pro','rayneo','ai_hud'::public.device_schema_type),
('rokid-max','rokid','display_ar'::public.device_schema_type),
('rokid-air','rokid','display_ar'::public.device_schema_type),
('rokid-ar-lite','rokid','display_ar'::public.device_schema_type),
('rokid-glasses','rokid','ai_hud'::public.device_schema_type),
('viture-pro','viture','display_ar'::public.device_schema_type),
('viture-one','viture','display_ar'::public.device_schema_type),
('viture-one-lite','viture','display_ar'::public.device_schema_type),
('inmo-air-2','inmo','ai_hud'::public.device_schema_type),
('inmo-go3','inmo','ai_hud'::public.device_schema_type),
('ray-ban-meta','meta','ai_hud'::public.device_schema_type),
('brilliant-labs-frame','brilliant-labs','ai_hud'::public.device_schema_type),
('even-realities-g1','even-realities','ai_hud'::public.device_schema_type)) AS e(slug,brand,schema_type) ON d.slug=e.slug
      WHERE d.brand_key<>e.brand OR d.schema_type IS NOT NULL AND d.schema_type<>e.schema_type) THEN
      RAISE EXCEPTION 'CANONICAL_EXISTING_IDENTITY_INCOMPATIBLE'; END IF;
  END $$;
  UPDATE public.devices d SET schema_type=e.schema_type FROM (VALUES ('xreal-one','xreal','display_ar'::public.device_schema_type),
('xreal-one-pro','xreal','display_ar'::public.device_schema_type),
('xreal-air-2-pro','xreal','display_ar'::public.device_schema_type),
('xreal-air-2-ultra','xreal','display_ar'::public.device_schema_type),
('xreal-air','xreal','display_ar'::public.device_schema_type),
('xreal-air-2','xreal','display_ar'::public.device_schema_type),
('rayneo-x2','rayneo','ai_hud'::public.device_schema_type),
('rayneo-air-2','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-2s','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-3s','rayneo','display_ar'::public.device_schema_type),
('rayneo-air-4-pro','rayneo','display_ar'::public.device_schema_type),
('rayneo-x3-pro','rayneo','ai_hud'::public.device_schema_type),
('rokid-max','rokid','display_ar'::public.device_schema_type),
('rokid-air','rokid','display_ar'::public.device_schema_type),
('rokid-ar-lite','rokid','display_ar'::public.device_schema_type),
('rokid-glasses','rokid','ai_hud'::public.device_schema_type),
('viture-pro','viture','display_ar'::public.device_schema_type),
('viture-one','viture','display_ar'::public.device_schema_type),
('viture-one-lite','viture','display_ar'::public.device_schema_type),
('inmo-air-2','inmo','ai_hud'::public.device_schema_type),
('inmo-go3','inmo','ai_hud'::public.device_schema_type),
('ray-ban-meta','meta','ai_hud'::public.device_schema_type),
('brilliant-labs-frame','brilliant-labs','ai_hud'::public.device_schema_type),
('even-realities-g1','even-realities','ai_hud'::public.device_schema_type)) AS e(slug,brand,schema_type)
    WHERE d.slug=e.slug AND d.brand_key=e.brand AND d.schema_type IS NULL;
COMMIT;
