INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-one', 'xreal', 'XREAL', 'XREAL One', 'XREAL One 是一款通过 USB-C 视频输出连接手机、掌机和电脑使用的显示型 AR 眼镜，主要用于便携大屏、观影、游戏和第二屏。眼镜内置 XREAL X1 芯片，但内容与算力仍主要依赖外部设备。', '它属于显示型路线，不提供独立应用生态。相比更早的观影眼镜，XREAL One 更强调显示稳定性、空间锚定和主机兼容范围。', '连接手机、掌机和电脑的高阶显示眼镜。', '2024', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"XREAL One 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL One 产品视觉', NULL, NULL, 'https://us.shop.xreal.com/products/xreal-one', 'display_glasses', '显示眼镜', '更适合观影、游戏、移动第二屏和显示链路研究。', '["观影与掌机大屏","便携第二屏","关注空间显示稳定性"]'::jsonb, '["期待完整独立系统","想直接安装普通应用","需要纯无线主机方案"]'::jsonb, '["需要支持视频输出的外部设备。","不是独立应用平台。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"4-microphone array"},{"field":"audio.speakers","label":"Speakers","value":"Bose-tuned open-ear speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription lens/frame"},{"field":"basic.weight_g","label":"Weight G","value":"82"},{"field":"compute.os","label":"Os","value":"XREAL spatial computing firmware"}]'::jsonb, '{"audio":{"microphones":"4-microphone array","speakers":"Bose-tuned open-ear speakers"},"basic":{"prescription_support":"Supported via prescription lens/frame","weight_g":"82"},"compute":{"os":"XREAL spatial computing firmware","soc":"XREAL X1"},"connectivity":{"android":"Supported when source supports compatible video output","hdmi":"Supported via adapter/accessory","ios":"Supported; model/adapter requirements vary","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"developer":{"spatial_api":"Native 3DoF; optional 6DoF with XREAL Eye"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<3; gamma 2.2","color_gamut":"108% sRGB","contrast_ratio":"100,000:1","display_technology":"Sony 0.68-inch Micro-OLED","electrochromic_dimming":"3 levels","eye_brightness":"600","fov_deg":"50","ipd_mm":"Software IPD adjustment","ocular_mode":"Binocular","optical_system":"Birdbath optics","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"accessory_6dof":"Supported with XREAL Eye","environment_sensors":"IMU/head-tracking sensors","eye_tracking":"No","hand_tracking":"No","native_3dof":"Yes","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'One series', 'display_ar', 'Display AR/XR glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-one-pro', 'xreal', 'XREAL', 'XREAL One Pro', 'XREAL One Pro 仍是外接式显示眼镜，重点在更大的视场角和更完整的显示体验。它同样依赖外部主机，不是独立系统。', '它更像 XREAL One 的显示升级版，适合已经接受显示眼镜路线、但希望获得更开阔画面的人。', '更偏显示体验升级，而不是独立系统替代。', NULL, NULL, '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"XREAL One Pro 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL One Pro 产品视觉', NULL, 'https://www.xreal.com/us/one-pro', NULL, 'display_glasses', '显示眼镜', '以显示体验升级为主，而不是独立系统替代。', '["想升级视场角","继续走显示眼镜路线","看重便携大屏体验"]'::jsonb, '["期待本机应用生态","需要纯无线方案","要低预算入门"]'::jsonb, '["仍然依赖外部主机。","重量和最终上市信息未在当前公开资料中稳定给出。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"4-microphone array"},{"field":"audio.speakers","label":"Speakers","value":"Bose-tuned open-ear speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription lens/frame"},{"field":"basic.weight_g","label":"Weight G","value":"87"},{"field":"compute.os","label":"Os","value":"XREAL spatial computing firmware"}]'::jsonb, '{"audio":{"microphones":"4-microphone array","speakers":"Bose-tuned open-ear speakers"},"basic":{"prescription_support":"Supported via prescription lens/frame","weight_g":"87"},"compute":{"os":"XREAL spatial computing firmware","soc":"XREAL X1"},"connectivity":{"android":"Supported when source supports compatible video output","hdmi":"Supported via adapter/accessory","ios":"Supported; model/adapter requirements vary","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"developer":{"spatial_api":"Native 3DoF; optional 6DoF with XREAL Eye"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<3; gamma 2.0","color_gamut":"108% sRGB","contrast_ratio":"100,000:1","display_technology":"Sony 0.55-inch Micro-OLED","electrochromic_dimming":"3 levels","eye_brightness":"700","fov_deg":"57","ipd_mm":"M: 57–66 mm; L: 66–75 mm; software IPD adjustment","ocular_mode":"Binocular","optical_system":"X-Prism optics","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"accessory_6dof":"Supported with XREAL Eye","environment_sensors":"IMU/head-tracking sensors","eye_tracking":"No","hand_tracking":"No","native_3dof":"Yes","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'One Pro', 'display_ar', 'Display AR/XR glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-air-2-pro', 'xreal', 'XREAL', 'XREAL Air 2 Pro', 'XREAL Air 2 Pro 是一款外接式显示眼镜，主要用于便携观影、游戏和第二屏。它不提供独立应用平台，核心仍是把手机、电脑或掌机的内容搬到眼前。', '这代产品的重点是轻量佩戴、1080p 显示和电致变色调光，适合把它当成成熟显示眼镜的代表样本。', '偏日常便携观影、游戏和轻办公外接。', '2023', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"XREAL Air 2 Pro 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL Air 2 Pro 产品视觉', NULL, NULL, 'https://us.shop.xreal.com/products/xreal-air-2-pro', 'display_glasses', '显示眼镜', '偏日常便携观影和轻办公外接。', '["观影与游戏","轻办公第二屏","对比主流显示眼镜"]'::jsonb, '["期待独立 AR 系统","依赖机身摄像与感知能力","希望完全无线使用"]'::jsonb, '["核心体验仍依赖外部设备。","兼容设备细项以官方兼容列表为准。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 microphones"},{"field":"audio.speakers","label":"Speakers","value":"2 speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"148.5×48×52"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame"},{"field":"basic.weight_g","label":"Weight G","value":"75"}]'::jsonb, '{"audio":{"microphones":"2 microphones","speakers":"2 speakers"},"basic":{"dimensions_mm":"148.5×48×52","prescription_support":"Supported via prescription frame","weight_g":"75"},"connectivity":{"android":"Supported when device provides DP video output","hdmi":"Supported via adapter","ios":"Supported with appropriate connection/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via adapter/accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via adapter/accessory"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<3","display_technology":"Sony 0.55-inch Micro-OLED","electrochromic_dimming":"3 levels: 0% / 35% / 100% shade","eye_brightness":"500","fov_deg":"46","ocular_mode":"Binocular","optical_system":"Optic Engine 2.0","refresh_rate_hz":"2D up to 120; 3D up to 90","resolution_per_eye":"1920×1080"},"tracking":{"accessory_3dof":"Supported with XREAL Beam / Beam Pro","accessory_6dof":"No","environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 2 series', 'display_ar', 'Display AR/XR glasses', 'Current / legacy product still sold in some regions') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-air-2-ultra', 'xreal', 'XREAL', 'XREAL Air 2 Ultra', 'XREAL Air 2 Ultra 更接近开发和空间计算实验设备，重点在 6DoF、手势和空间交互验证，而不是普通观影路线。它仍需要外部主机供电和提供内容。', '这款产品的价值在于开发和实验，适合研究传感器、空间输入和 SDK 边界，不适合把它当作单纯的观影升级款。', '开发和空间交互实验优先的 XREAL 机型。', '2024', NULL, '开发设备', '开发设备', '{"imageUrl":null,"imageAlt":"XREAL Air 2 Ultra 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL Air 2 Ultra 产品视觉', NULL, NULL, 'https://us.shop.xreal.com/products/xreal-air-2-ultra/', 'developer_device', '开发设备', '重在开发与实验，不是纯消费级显示设备。', '["空间计算实验","开发验证","研究传感与输入"]'::jsonb, '["只想观影","期待低门槛开箱即用","需要成熟消费生态"]'::jsonb, '["重点是开发与实验。","很多体验仍建立在外部主机和开发环境之上。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 microphones"},{"field":"audio.speakers","label":"Speakers","value":"2 speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"148.5×48×161.5 (in use)"},{"field":"basic.material","label":"Material","value":"Titanium frame"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via detachable prescription frame"}]'::jsonb, '{"audio":{"microphones":"2 microphones","speakers":"2 speakers"},"basic":{"dimensions_mm":"148.5×48×161.5 (in use)","material":"Titanium frame","prescription_support":"Supported via detachable prescription frame","weight_g":"83"},"connectivity":{"android":"Supported","hdmi":"Supported via compatible adapter","ios":"Supported on compatible iPhone/iPad connection","macos":"Supported","nintendo_switch":"Supported","playstation":"Supported","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported in some official regional compatibility materials"},"developer":{"ar_foundation":"Supported","openxr":"No","sdk":"XREAL SDK 3.0","spatial_api":"6DoF, hand tracking, depth mesh, spatial anchors, plane detection, image tracking","unity":"Supported"},"display":{"binocular_resolution":"3840×1080","display_technology":"Sony Micro-OLED","electrochromic_dimming":"3 levels","eye_brightness":"2D 30–500; 3D 20–250","fov_deg":"52","ocular_mode":"Binocular","refresh_rate_hz":"2D up to 120; 3D up to 90","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"2 × 3D environment sensors; IMU","eye_tracking":"No","hand_tracking":"Yes","native_3dof":"Yes","native_6dof":"Yes","slam":"Yes"}}'::jsonb, 'published', 'Air 2 Ultra', 'display_ar', 'Display AR/XR glasses', 'Developer / spatial computing product') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-air', 'xreal', 'XREAL', 'XREAL Air', 'XREAL Air 是 XREAL 早期主流显示眼镜，定位是连接手机、掌机和电脑使用的便携大屏。它不提供独立系统，重点是轻量观影、游戏和第二屏。', '这代产品奠定了后续 XREAL 显示眼镜路线：外接设备供内容与算力，眼镜负责把屏幕体验做得更贴近日常佩戴。对比新型号，它更适合拿来理解消费级显示眼镜的起点。', 'XREAL 早期消费级显示眼镜。', '2022', '旧款', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"XREAL Air 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL Air 产品视觉', NULL, 'https://www.xreal.com/about', NULL, 'display_glasses', '显示眼镜', 'XREAL 早期消费级显示眼镜。', '["轻量观影","掌机与电脑第二屏","了解显示眼镜起点"]'::jsonb, '["期待独立系统","依赖本机感知与拍摄","需要最新舒适度设计"]'::jsonb, '["需要支持视频输出的外部设备。","属于早期产品，当前不是品牌主推型号。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 microphones"},{"field":"audio.speakers","label":"Speakers","value":"2 speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"148.5×60×52"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame"},{"field":"basic.weight_g","label":"Weight G","value":"79"}]'::jsonb, '{"audio":{"microphones":"2 microphones","speakers":"2 speakers"},"basic":{"dimensions_mm":"148.5×60×52","prescription_support":"Supported via prescription frame","weight_g":"79"},"connectivity":{"android":"Supported when device provides DP video output","hdmi":"Supported via adapter","ios":"Supported with appropriate connection/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via adapter","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via adapter"},"display":{"binocular_resolution":"3840×1080","display_technology":"Sony Micro-OLED","electrochromic_dimming":"No","eye_brightness":"400","fov_deg":"46","ocular_mode":"Binocular","refresh_rate_hz":"2D up to 120; 3D up to 90","resolution_per_eye":"1920×1080"},"tracking":{"accessory_3dof":"Supported with XREAL Beam","accessory_6dof":"No","environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Original Air', 'display_ar', 'Display AR/XR glasses', 'Discontinued; official refurbished stock may remain') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('xreal-air-2', 'xreal', 'XREAL', 'XREAL Air 2', 'XREAL Air 2 是更成熟的一代显示眼镜，继续围绕手机、掌机和电脑外接使用，重点是减重、画质和日常佩戴体验。', '它延续 XREAL 的显示型路线，不尝试变成独立系统。相比早期型号，Air 2 更适合把它当作长期携带的大屏外设，而不是一次性尝鲜设备。', '日常便携观影与第二屏显示眼镜。', '2023', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"XREAL Air 2 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'XREAL Air 2 产品视觉', NULL, 'https://us.shop.xreal.com/products/xreal-air-2', 'https://us.shop.xreal.com/products/xreal-air-2', 'display_glasses', '显示眼镜', '日常便携观影与第二屏显示眼镜。', '["便携观影","掌机/电脑第二屏","想要轻量显示眼镜"]'::jsonb, '["期待独立应用生态","需要摄像头和空间感知","希望完全无线"]'::jsonb, '["内容与算力仍依赖外部设备。","不提供独立相机或本机应用生态。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 microphones"},{"field":"audio.speakers","label":"Speakers","value":"2nd-generation open-ear audio; 2 speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"148.5×48×52"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame"},{"field":"basic.weight_g","label":"Weight G","value":"72"}]'::jsonb, '{"audio":{"microphones":"2 microphones","speakers":"2nd-generation open-ear audio; 2 speakers"},"basic":{"dimensions_mm":"148.5×48×52","prescription_support":"Supported via prescription frame","weight_g":"72"},"connectivity":{"android":"Supported when device provides DP video output","hdmi":"Supported via adapter","ios":"Supported with appropriate connection/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via adapter","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via adapter"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<3","display_technology":"Sony 0.55-inch Micro-OLED","electrochromic_dimming":"No","eye_brightness":"500","fov_deg":"46","ocular_mode":"Binocular","optical_system":"Optic Engine 2.0","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"accessory_3dof":"Supported with XREAL Beam / Beam Pro","accessory_6dof":"No","environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 2 series', 'display_ar', 'Display AR/XR glasses', 'Current / legacy product still sold in some regions') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-x2', 'rayneo', 'RayNeo', 'RayNeo X2', 'RayNeo X2 是一款带独立计算能力的 AR 眼镜，重点是翻译、导航、拍摄和提示式信息叠加，不是传统外接大屏显示眼镜。', '它更接近独立系统路线，价值在于系统级交互、轻导航和信息提示，而不是观影或第二屏。', '强调独立系统与轻量信息叠加的 RayNeo 路线。', '2023', '未上市', 'AR 眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo X2 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo X2 产品视觉', NULL, 'https://www.rayneo.com/en-ca/products/tcl-rayneo-x2', NULL, 'ar_glasses', 'AR 眼镜', '强调系统级提示与信息叠加，而不是外接大屏。', '["观察独立 AR 交互","导航与翻译场景","系统级样本研究"]'::jsonb, '["只想看大屏","期望低成本娱乐设备","需要轻量显示眼镜"]'::jsonb, '["当前公开资料对重量和价格仍不稳定。","不是传统第二屏产品。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"Multimodal AI / GPT-4V-era official integrations"},{"field":"ai_features.navigation","label":"Navigation","value":"SLAM navigation"},{"field":"ai_features.other_features","label":"Other Features","value":"Gesture interaction; AI recognition"},{"field":"ai_features.translation","label":"Translation","value":"Yes"},{"field":"ai_features.vision_ai","label":"Vision Ai","value":"Yes"}]'::jsonb, '{"ai_features":{"ai_assistant":"Multimodal AI / GPT-4V-era official integrations","navigation":"SLAM navigation","other_features":"Gesture interaction; AI recognition","translation":"Yes","vision_ai":"Yes"},"basic":{"dimensions_mm":"Unfolded 190.5×165.5×66.5; folded 60×165.5×66.5","weight_g":"119"},"battery":{"battery_capacity_mah":"590"},"camera":{"camera_mp":"16 MP","camera_present":"Yes","video_resolution_fps":"1080p video"},"compute":{"ram":"6 GB","soc":"Qualcomm Snapdragon XR2","storage":"128 GB"},"connectivity":{"android":"Android 9+; stability varies by model","bluetooth":"Bluetooth 5.2","gps":"Yes","ios":"iOS 10+; stability varies by model","usb":"USB 2.0","wifi":"Wi-Fi 5"},"developer":{"sideload":"ADB APK sideload supported"},"display":{"color":"Full color","contrast_ratio":"100,000:1","display_present":"Yes","display_technology":"Full-color MicroLED","eye_brightness":"1000","ocular_mode":"Binocular","optical_system":"Binocular optical waveguide"},"privacy":{"camera_indicator":"Yes; status LED for photo/video","physical_camera_cover":"No"},"tracking":{"hand_tracking":"Gesture recognition supported","sensors":"Accelerometer, gyroscope, compass, pressure sensor, GPS","slam":"Yes"}}'::jsonb, 'published', 'X2', 'ai_hud', 'AI/HUD smart glasses', 'Sold out; RayNeo 2026 brand material also describes X2 as discontinued/reference-only') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-air-2', 'rayneo', 'RayNeo', 'RayNeo Air 2', 'RayNeo Air 2 是一款外接显示眼镜，主打 1080p Micro‑OLED 屏幕、120Hz 刷新率和广泛的设备兼容性。它更像私人大屏，而不是独立 AR 系统。', '这款产品强调连接 iPhone、掌机、MacBook 与游戏主机的即插即用体验。它适合看视频、玩游戏和做轻办公，但核心仍是显示终端。', 'RayNeo 入门到主流段的显示眼镜。', '2024', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo Air 2 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo Air 2 产品视觉', NULL, 'https://www.rayneo.com/products/rayneo-air-2-xr-glasses', 'https://www.rayneo.com/products/rayneo-air-2-xr-glasses', 'display_glasses', '显示眼镜', 'RayNeo 入门到主流段的显示眼镜。', '["掌机与主机游戏","便携观影","跨设备第二屏"]'::jsonb, '["期待独立系统","需要原生空间感知","只想用无线投屏"]'::jsonb, '["需要 DP 输出或转接器。","不提供独立应用平台。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"2 speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription insert/solution"},{"field":"basic.weight_g","label":"Weight G","value":"76"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible USB-C DP devices; non-DP devices may require adapter"},{"field":"connectivity.hdmi","label":"Hdmi","value":"Supported via adapter"}]'::jsonb, '{"audio":{"speakers":"2 speakers"},"basic":{"prescription_support":"Supported via prescription insert/solution","weight_g":"76"},"connectivity":{"android":"Supported on compatible USB-C DP devices; non-DP devices may require adapter","hdmi":"Supported via adapter","ios":"Supported; Lightning models require adapter, USB-C models depend on video output/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"display":{"binocular_resolution":"3840×1080","display_technology":"Micro-OLED","electrochromic_dimming":"No","eye_box_mm":"10×6.5","eye_brightness":"600","fov_deg":"46","ocular_mode":"Binocular","panel_or_projector_brightness":"4000","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 2', 'display_ar', 'Display AR/XR glasses', 'Current / regional availability varies') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-air-2s', 'rayneo', 'RayNeo', 'RayNeo Air 2s', 'RayNeo Air 2s 延续显示眼镜路线，重点是 120Hz 刷新率、600 nits 亮度和更均衡的声音与佩戴调节。', '相比 Air 2，它更强调长时间使用时的舒适度与音频表现，依然主要服务于手机、掌机和主机的大屏输出场景。', '强调佩戴与音频升级的显示眼镜。', '2024', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo Air 2s 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo Air 2s 产品视觉', NULL, 'https://eu.rayneo.com/products/rayneo-air_2s', 'https://eu.rayneo.com/products/rayneo-air_2s', 'display_glasses', '显示眼镜', '强调佩戴与音频升级的显示眼镜。', '["观影与游戏","想要更稳妥的佩戴调节","跨设备显示"]'::jsonb, '["需要独立计算平台","需要本机相机","只接受无线方案"]'::jsonb, '["依赖外部设备供内容与算力。","核心升级仍在显示与音频层。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"4 Push-Push speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription insert/solution"},{"field":"basic.weight_g","label":"Weight G","value":"76"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible USB-C DP devices; non-DP devices may require adapter"},{"field":"connectivity.hdmi","label":"Hdmi","value":"Supported via adapter"}]'::jsonb, '{"audio":{"speakers":"4 Push-Push speakers"},"basic":{"prescription_support":"Supported via prescription insert/solution","weight_g":"76"},"connectivity":{"android":"Supported on compatible USB-C DP devices; non-DP devices may require adapter","hdmi":"Supported via adapter","ios":"Supported; Lightning models require adapter, USB-C models depend on video output/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"3 color modes; distortion ≤1%","display_technology":"Sony Micro-OLED","electrochromic_dimming":"No","eye_box_mm":"11.2×6.5","eye_brightness":"600","fov_deg":"46","ocular_mode":"Binocular","panel_or_projector_brightness":"5000","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 2s', 'display_ar', 'Display AR/XR glasses', 'Current / regional availability varies') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-air-3s', 'rayneo', 'RayNeo', 'RayNeo Air 3s', 'RayNeo Air 3s 是更偏影音体验的一代显示眼镜，重点在 HueView Micro‑OLED、120Hz、650 nits 和更成熟的眼部舒适设计。', '它仍是外接显示路线，但在色彩、亮度、音频和护眼能力上更完整，适合作为私人影院或掌机大屏来理解。', '高色域、高舒适度的显示眼镜。', '2025', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo Air 3s 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo Air 3s 产品视觉', NULL, 'https://eu.rayneo.com/products/rayneo-air-3s-xr-glasses', 'https://eu.rayneo.com/products/rayneo-air-3s-xr-glasses', 'display_glasses', '显示眼镜', '高色域、高舒适度的显示眼镜。', '["电影与串流","掌机大屏","更在意色彩与舒适度"]'::jsonb, '["需要独立系统","需要拍摄和传感","想极简低价试水"]'::jsonb, '["依赖外部设备输出内容。","主要优势在影音体验，不是开放开发平台。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"4 speakers; Whisper Mode 2.0"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription insert/solution"},{"field":"basic.weight_g","label":"Weight G","value":"76"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible USB-C DP devices; non-DP devices may require adapter"},{"field":"connectivity.hdmi","label":"Hdmi","value":"Supported via adapter"}]'::jsonb, '{"audio":{"speakers":"4 speakers; Whisper Mode 2.0"},"basic":{"prescription_support":"Supported via prescription insert/solution","weight_g":"76"},"connectivity":{"android":"Supported on compatible USB-C DP devices; non-DP devices may require adapter","hdmi":"Supported via adapter","ios":"Supported; Lightning models require adapter, USB-C models depend on video output/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<2; 3840 Hz hybrid dimming","color_gamut":"145% sRGB; 98% DCI-P3","contrast_ratio":"200,000:1","display_technology":"HueView Micro-OLED","electrochromic_dimming":"No","eye_brightness":"650","fov_deg":"46","ocular_mode":"Binocular","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 3s', 'display_ar', 'Display AR/XR glasses', 'Current / regional availability varies') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-air-4-pro', 'rayneo', 'RayNeo', 'RayNeo Air 4 Pro', 'RayNeo Air 4 Pro 是当前更高阶的显示眼镜，主打 HDR10、1200 nits 峰值亮度、120Hz 和 B&O 调音的四扬声器。', '它继续服务于观影、游戏和移动大屏，但画质、色彩和声音都明显拉高，更像是显示眼镜路线里的旗舰方案。', 'RayNeo 当前高阶显示眼镜。', '2026', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo Air 4 Pro 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo Air 4 Pro 产品视觉', NULL, 'https://www.rayneo.com/products/rayneo-air-4-pro-ar-glasses', 'https://www.rayneo.com/products/rayneo-air-4-pro-ar-glasses', 'display_glasses', '显示眼镜', 'RayNeo 当前高阶显示眼镜。', '["HDR 观影","高规格掌机与主机体验","想要旗舰显示效果"]'::jsonb, '["想低成本试水","需要独立系统","需要真实世界拍摄能力"]'::jsonb, '["仍然需要外部设备输出。","提升主要集中在显示与音频，不是独立系统平台。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"4 Bang & Olufsen-tuned speakers; Whisper Mode 2.0"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription insert/solution"},{"field":"basic.weight_g","label":"Weight G","value":"76"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible USB-C DP devices; non-DP devices may require adapter"},{"field":"connectivity.hdmi","label":"Hdmi","value":"Supported via adapter"}]'::jsonb, '{"audio":{"speakers":"4 Bang & Olufsen-tuned speakers; Whisper Mode 2.0"},"basic":{"prescription_support":"Supported via prescription insert/solution","weight_g":"76"},"connectivity":{"android":"Supported on compatible USB-C DP devices; non-DP devices may require adapter","hdmi":"Supported via adapter","ios":"Supported; Lightning models require adapter, USB-C models depend on video output/accessory","macos":"Supported","nintendo_switch":"Supported via compatible accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI accessory"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"ΔE<2; HDR10; 3840 Hz dimming","color_gamut":"145% sRGB; 98% DCI-P3","contrast_ratio":"200,000:1","display_technology":"0.6-inch SeeYa Micro-OLED / HueView 2.0","electrochromic_dimming":"No","eye_box_mm":"14×7","eye_brightness":"1200","fov_deg":"46","ocular_mode":"Binocular","ppd":"49","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air 4 Pro', 'display_ar', 'Display AR/XR glasses', 'Current / regional availability varies') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rayneo-x3-pro', 'rayneo', 'RayNeo', 'RayNeo X3 Pro', 'RayNeo X3 Pro 是更偏独立计算和 AI 助手路线的双目 AR 眼镜，重点不再是私人大屏，而是常显信息、空间定位和本机计算。', '它采用双目全彩 MicroLED、Snapdragon AR1 和 6DoF + SLAM，方向更接近下一代 AI+AR 智能眼镜。和 Air 系列相比，它更像一台头戴式计算机。', 'RayNeo 面向 AI+AR 的独立眼镜路线。', '2025', '在售', 'AR 眼镜', NULL, '{"imageUrl":null,"imageAlt":"RayNeo X3 Pro 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'RayNeo X3 Pro 产品视觉', NULL, 'https://eu.rayneo.com/products/x3-pro-ai-display-glasses', 'https://eu.rayneo.com/products/x3-pro-ai-display-glasses', 'ar_glasses', 'AR 眼镜', 'RayNeo 面向 AR / AI 的独立眼镜路线。', '["关注 AI+AR 形态","想研究独立交互","需要更轻量的常显信息"]'::jsonb, '["只想看大屏电影","想要低价显示外设","接受度对早期平台较低"]'::jsonb, '["平台仍属早期形态。","相比纯显示眼镜，内容生态与成本门槛更高。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"Gemini Live"},{"field":"ai_features.navigation","label":"Navigation","value":"Yes"},{"field":"ai_features.other_features","label":"Other Features","value":"Creator Mode; music; camera"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"Yes"},{"field":"ai_features.transcription","label":"Transcription","value":"Meeting notes / transcription"}]'::jsonb, '{"ai_features":{"ai_assistant":"Gemini Live","navigation":"Yes","other_features":"Creator Mode; music; camera","teleprompter":"Yes","transcription":"Meeting notes / transcription","translation":"14-language real-time translation","vision_ai":"Yes"},"audio":{"microphones":"3 microphones"},"basic":{"prescription_support":"Supported","weight_g":"76±1"},"battery":{"battery_capacity_mah":"245","charging_time":"About 38 min to full"},"camera":{"camera_mp":"12 MP","camera_present":"Yes","camera_sensor":"Sony IMX681 main camera","secondary_spatial_camera":"Yes; OV spatial camera","video_resolution_fps":"Up to 4K / 3K capture depending mode"},"compute":{"os":"RayNeo AIOS","ram":"4 GB","soc":"Qualcomm Snapdragon AR1 Gen 1","storage":"32 GB"},"connectivity":{"bluetooth":"Bluetooth 5.3","usb":"USB-C / USB 2.0","wifi":"Wi-Fi 6"},"developer":{"sdk":"RayNeo ARDK","spatial_api":"Android ARDK / Unity ARDK; 6DoF + SLAM","unity":"Supported"},"display":{"color":"16.77M colors","display_present":"Yes","display_technology":"Full-color MicroLED","eye_brightness":"3500 average / 6000 peak","fov_deg":"30","ocular_mode":"Binocular","optical_system":"Binocular diffractive waveguide","resolution_per_eye":"640×480"},"privacy":{"physical_camera_cover":"No"},"tracking":{"native_3dof":"Yes","native_6dof":"Yes in Creator Mode","sensors":"Accelerometer, gyroscope, magnetometer, ambient light, wear detection","slam":"Yes"}}'::jsonb, 'published', 'X3 Pro', 'ai_hud', 'AI/HUD smart glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rokid-max', 'rokid', 'Rokid', 'Rokid Max', 'Rokid Max 是一款外接式显示眼镜，主要用于观影、游戏和大屏外接。它不提供独立系统，核心是把兼容主机的画面搬到眼前。', '这款产品适合作为主流显示眼镜样本，重点看画面、佩戴、连接方式和移动娱乐场景。', '观影、大屏和游戏外接路线。', '2023', NULL, '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"Rokid Max 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Rokid Max 产品视觉', NULL, 'https://global.rokid.com/products/rokid-max', NULL, 'display_glasses', '显示眼镜', '观影、大屏和游戏外接路线。', '["便携观影","掌机 / 主机外接","对比显示眼镜体验"]'::jsonb, '["需要独立系统","想在眼镜端运行应用","追求纯无线使用"]'::jsonb, '["核心体验依赖外部主机。","无线能力主要依赖额外配件。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 noise-cancelling microphones"},{"field":"audio.speakers","label":"Speakers","value":"2 directional speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"174.37×158.71×44.94"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Built-in myopia adjustment; prescription use also possible depending on user"},{"field":"basic.weight_g","label":"Weight G","value":"75"}]'::jsonb, '{"audio":{"microphones":"2 noise-cancelling microphones","speakers":"2 directional speakers"},"basic":{"dimensions_mm":"174.37×158.71×44.94","prescription_support":"Built-in myopia adjustment; prescription use also possible depending on user","weight_g":"75"},"connectivity":{"android":"Supported on USB-C DP compatible devices","hdmi":"Supported via adapter","ios":"Supported with appropriate adapter","macos":"Supported","nintendo_switch":"Supported via compatible adapter/accessory","playstation":"Supported via HDMI adapter","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via HDMI adapter"},"display":{"binocular_resolution":"3840×1080","color_accuracy":"8-bit / 16.7M colors","color_gamut":"108% sRGB","contrast_ratio":"100,000:1","display_technology":"Sony Micro-OLED","electrochromic_dimming":"No","eye_brightness":"600","fov_deg":"50","myopia_adjustment_d":"0 to -6D","ocular_mode":"Binocular","ppd":"45","refresh_rate_hz":"Up to 120","resolution_per_eye":"1920×1080"},"tracking":{"accessory_3dof":"Supported with Rokid Station 2","accessory_6dof":"No","environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Max', 'display_ar', 'Display AR/XR glasses', 'Current / legacy product') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rokid-air', 'rokid', 'Rokid', 'Rokid Air', 'Rokid Air 是 Rokid 早期面向消费市场的显示眼镜，重点在手机外接观影和轻量信息查看，不是独立系统设备。', '它是 Rokid 后续 Max 系列之前的重要起点，帮助理解品牌从早期 AR 眼镜向更成熟显示眼镜演进的路径。', 'Rokid 早期消费级显示眼镜。', '2021', '旧款', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"Rokid Air 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Rokid Air 产品视觉', NULL, 'https://air.rokid.com/', NULL, 'display_glasses', '显示眼镜', 'Rokid 早期消费级显示眼镜。', '["了解 Rokid 早期产品路线","轻量观影","对比新旧显示眼镜差异"]'::jsonb, '["期待最新画质","需要独立应用生态","想要更强舒适度"]'::jsonb, '["属于较早期型号。","显示与佩戴规格已落后于新款。"]'::jsonb, '[{"field":"audio.microphones","label":"Microphones","value":"2 noise-cancelling microphones"},{"field":"audio.speakers","label":"Speakers","value":"2 directional speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Built-in myopia adjustment"},{"field":"basic.weight_g","label":"Weight G","value":"83"},{"field":"connectivity.android","label":"Android","value":"Android 10+ on compatible USB-C DP devices"}]'::jsonb, '{"audio":{"microphones":"2 noise-cancelling microphones","speakers":"2 directional speakers"},"basic":{"prescription_support":"Built-in myopia adjustment","weight_g":"83"},"connectivity":{"android":"Android 10+ on compatible USB-C DP devices","hdmi":"Supported via adapter","ios":"Supported via appropriate adapter","macos":"Supported","nintendo_switch":"Supported via adapter","playstation":"Supported via adapter","usb_c_dp":"Supported","windows":"Supported","xbox":"Supported via adapter"},"display":{"binocular_resolution":"3840×1080","contrast_ratio":"100,000:1","display_technology":"Micro-OLED","electrochromic_dimming":"No","fov_deg":"43","myopia_adjustment_d":"0 to -5D","ocular_mode":"Binocular","panel_or_projector_brightness":"1800","refresh_rate_hz":"60","resolution_per_eye":"1920×1080"},"tracking":{"accessory_3dof":"No","accessory_6dof":"No","environment_sensors":"Enhanced 9-axis sensor; proximity sensor","eye_tracking":"No","hand_tracking":"No","native_3dof":"No","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Air', 'display_ar', 'Display AR/XR glasses', 'Legacy / discontinued-era product') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rokid-ar-lite', 'rokid', 'Rokid', 'Rokid AR Lite', 'Rokid AR Lite 不是单独一副眼镜，而是 Max 2 + Station 2 组成的 AR 套装，目标是把大屏显示推进到多窗口和信息叠加。', '它比普通显示眼镜更接近多窗口 AR 套装体验，但核心依旧建立在眼镜与主机协同上，而不是把全部计算放进眼镜本体。', 'Rokid 面向多窗口 AR 的组合式套装。', '2024', '在售', 'AR 眼镜', NULL, '{"imageUrl":null,"imageAlt":"Rokid AR Lite 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Rokid AR Lite 产品视觉', NULL, 'https://arlite.rokid.com/', 'https://arlite.rokid.com/', 'ar_glasses', 'AR 眼镜', 'Rokid 面向多窗口 AR 的组合式套装。', '["多窗口空间显示","想研究眼镜+主机协同","关注空间视频与空间浏览"]'::jsonb, '["只想买一副简单显示眼镜","只想要轻量佩戴","期待纯眼镜端完整系统"]'::jsonb, '["它是套装，不是单一眼镜。","Station 2 是体验成立的关键部分。"]'::jsonb, '[{"field":"basic.prescription_support","label":"Prescription Support","value":"Max 2: built-in 0 to -6D myopia adjustment"},{"field":"basic.weight_g","label":"Weight G","value":"75 (glasses only)"},{"field":"compute.os","label":"Os","value":"YodaOS-Master (Station 2)"},{"field":"compute.ram","label":"Ram","value":"8 GB (Station 2)"},{"field":"compute.storage","label":"Storage","value":"128 GB (Station 2)"}]'::jsonb, '{"basic":{"prescription_support":"Max 2: built-in 0 to -6D myopia adjustment","weight_g":"75 (glasses only)"},"compute":{"os":"YodaOS-Master (Station 2)","ram":"8 GB (Station 2)","storage":"128 GB (Station 2)"},"connectivity":{"android":"Supported / Station 2 is the primary spatial compute source","bluetooth":"Bluetooth 5.2 (Station 2)","hdmi":"Supported via adapter","ios":"Supported with compatible setup","macos":"Supported as display source where compatible","nintendo_switch":"Supported with compatible setup","playstation":"Supported with compatible setup","usb_c_dp":"Supported","wifi":"Wi-Fi 6 (Station 2)","windows":"Supported as display source where compatible","xbox":"Supported with compatible setup"},"developer":{"spatial_api":"3DoF spatial modes through Station 2"},"display":{"color_gamut":"108% sRGB","contrast_ratio":"100,000:1","display_technology":"Micro-OLED (Max 2)","electrochromic_dimming":"No","eye_brightness":"600","fov_deg":"50","ipd_mm":"Adjustable","myopia_adjustment_d":"0 to -6D","ocular_mode":"Binocular","refresh_rate_hz":"60–120","resolution_per_eye":"Up to 1920×1200; default 1920×1080"},"power":{"battery_capacity_mah":"5000 (Station 2)","built_in_battery":"Station 2 has built-in battery","charging":"18 W","typical_runtime":"Approximately 5 h (Station 2)"},"tracking":{"accessory_3dof":"Yes with included Station 2","accessory_6dof":"No","environment_sensors":"9-axis IMU in Station 2","eye_tracking":"No","hand_tracking":"No","native_3dof":"No (glasses alone)","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'AR Lite bundle', 'display_ar', 'Display AR/XR bundle (Rokid Max 2 + Station 2)', 'Current / bundle') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('rokid-glasses', 'rokid', 'Rokid', 'Rokid Glasses', 'Rokid Glasses 更偏 AI 眼镜路线，重点是拍摄、语音和轻量信息入口，不是以大屏显示为核心的观影设备。', '它更适合被看作日常佩戴的 AI 硬件入口，核心不在显示，而在语音、拍摄和轻量提示。', '更偏无感佩戴和信息入口的 AI 眼镜。', NULL, '在售', 'AI 眼镜', NULL, '{"imageUrl":null,"imageAlt":"Rokid Glasses 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Rokid Glasses 产品视觉', NULL, 'https://global.rokid.com/products/rokid-glasses', NULL, 'ai_glasses', 'AI 眼镜', '更偏无感佩戴和信息入口。', '["语音入口","轻量拍摄","研究 AI 穿戴入口"]'::jsonb, '["期待大屏显示","想做空间界面开发","依赖长时续航"]'::jsonb, '["当前公开显示参数有限。","更适合 AI 入口，而不是观影或空间显示。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"ChatGPT / Qwen and region-dependent AI services"},{"field":"ai_features.navigation","label":"Navigation","value":"Yes"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"Yes"},{"field":"ai_features.transcription","label":"Transcription","value":"Meeting transcription"},{"field":"ai_features.translation","label":"Translation","value":"Up to 89 languages"}]'::jsonb, '{"ai_features":{"ai_assistant":"ChatGPT / Qwen and region-dependent AI services","navigation":"Yes","teleprompter":"Yes","transcription":"Meeting transcription","translation":"Up to 89 languages","vision_ai":"Yes"},"audio":{"microphones":"4 microphones","speakers":"2 directional / open-ear speakers"},"basic":{"dimensions_mm":"143×44×160.5","prescription_support":"Supported","weight_g":"49"},"battery":{"battery_capacity_mah":"210","charging_case":"Official materials indicate multiple recharges; current product materials have stated up to about 10 full charges","charging_time":"About 20 min to 80%"},"camera":{"camera_fov_deg":"109","camera_mp":"12 MP","camera_present":"Yes","camera_sensor":"Sony IMX681","photo_resolution":"3024×4032","secondary_spatial_camera":"No","video_resolution_fps":"Up to 3K @ 30 fps"},"compute":{"ram":"2 GB","soc":"Qualcomm Snapdragon AR1 Gen 1 + NXP RT600","storage":"32 GB"},"connectivity":{"android":"Supported via companion ecosystem","bluetooth":"Bluetooth 5.3","ios":"Supported via companion ecosystem","usb":"Magnetic charging / data interface as specified by accessory ecosystem","wifi":"Wi-Fi 6"},"developer":{"sdk":"Rokid SDK"},"display":{"color":"Green monochrome","display_present":"Yes","display_technology":"Green MicroLED","eye_brightness":"1500","fov_deg":"30","ocular_mode":"Binocular","optical_system":"Single-engine dual-output diffractive waveguide","resolution_per_eye":"480×400"},"privacy":{"camera_indicator":"Yes; RGB status indicator","camera_indicator_occlusion_detection":"Yes; P-sensor / indicator anti-occlusion mechanism","physical_camera_cover":"No","privacy_notes":"IPX4 product protection rating is publicly listed."}}'::jsonb, 'published', 'Rokid Glasses', 'ai_hud', 'AI/HUD smart glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('viture-pro', 'viture', 'VITURE', 'VITURE Pro', 'VITURE Pro 是一款外接式显示眼镜，主要用于便携观影、游戏和第二屏。它不是独立计算设备，内容和交互仍由外部主机提供。', '这代产品把亮度、近视调节和生态配件做得更完整，适合关注移动娱乐与显示体验的人。', '偏便携娱乐和外接显示生态。', '2024', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"VITURE Pro 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'VITURE Pro 产品视觉', NULL, 'https://www.viture.com/product/viture-luma-pro-xr-glasses', NULL, 'display_glasses', '显示眼镜', '偏便携娱乐和外接显示生态。', '["便携观影","对比显示路线","外接娱乐设备"]'::jsonb, '["期待独立 AI / AR 系统","优先开发开放平台","只想要纯无线眼镜"]'::jsonb, '["核心体验依赖外部主机。","无线视频与联网能力依赖颈带或移动底座。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"Built-in spatial/open-ear speakers"},{"field":"basic.material","label":"Material","value":"Aircraft-grade aluminum body + titanium hinges"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame / built-in diopter adjustment"},{"field":"basic.weight_g","label":"Weight G","value":"77"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible video-output devices"}]'::jsonb, '{"audio":{"speakers":"Built-in spatial/open-ear speakers"},"basic":{"material":"Aircraft-grade aluminum body + titanium hinges","prescription_support":"Supported via prescription frame / built-in diopter adjustment","weight_g":"77"},"connectivity":{"android":"Supported on compatible video-output devices","hdmi":"Supported via adapter/dock","ios":"Supported with appropriate VITURE adapter/accessory","macos":"Supported","nintendo_switch":"Supported via appropriate accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported (connector/cable architecture varies by model)","windows":"Supported","xbox":"Supported via HDMI accessory"},"developer":{"sdk":"VITURE XR Glasses SDK","spatial_api":"3DoF head tracking supported by official VITURE XR Glasses SDK"},"display":{"binocular_resolution":"3840×1080","color_gamut":"108% sRGB","contrast_ratio":"100,000:1","display_technology":"Micro-OLED","electrochromic_dimming":"Yes; electrochromic transmittance about 0.5–40%, haze <1%, ~0.1 s","eye_brightness":"1000","fov_deg":"46","ipd_mm":"56.5–70.5","myopia_adjustment_d":"0 to -5D","ocular_mode":"Binocular","panel_or_projector_brightness":"4000","ppd":"49","refresh_rate_hz":"120 / 90 / 60","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"Yes","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'Pro', 'display_ar', 'Display AR/XR glasses', 'Current / legacy Pro model') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('viture-one', 'viture', 'VITURE', 'VITURE One', 'VITURE One 是 VITURE 早期显示眼镜，核心是把手机、掌机和电脑的画面变成随身私人屏幕。它仍然是外接显示路线。', '这代产品已经体现出 VITURE 的连接和交互思路，比如磁吸连接与 3DoF 支持。相比后续型号，它更适合被看作品牌路线的起点。', 'VITURE 早期显示眼镜。', '2022', '旧款', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"VITURE One 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'VITURE One 产品视觉', NULL, 'https://www.viture.com/', NULL, 'display_glasses', '显示眼镜', 'VITURE 早期显示眼镜。', '["了解 VITURE 生态起点","便携观影","外接掌机大屏"]'::jsonb, '["期待最新亮度与刷新率","需要独立系统","只接受极简 USB-C 直连"]'::jsonb, '["属于较早期一代。","显示与连接设计已被后续型号更新。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"Built-in spatial/open-ear speakers"},{"field":"basic.dimensions_mm","label":"Dimensions Mm","value":"163×47.7×53.7 (VITURE One folded)"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame / built-in diopter adjustment"},{"field":"basic.weight_g","label":"Weight G","value":"78"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible video-output devices"}]'::jsonb, '{"audio":{"speakers":"Built-in spatial/open-ear speakers"},"basic":{"dimensions_mm":"163×47.7×53.7 (VITURE One folded)","prescription_support":"Supported via prescription frame / built-in diopter adjustment","weight_g":"78"},"connectivity":{"android":"Supported on compatible video-output devices","hdmi":"Supported via adapter/dock","ios":"Supported with appropriate VITURE adapter/accessory","macos":"Supported","nintendo_switch":"Supported via appropriate accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported (connector/cable architecture varies by model)","windows":"Supported","xbox":"Supported via HDMI accessory"},"developer":{"sdk":"VITURE XR Glasses SDK","spatial_api":"3DoF head tracking supported by official VITURE XR Glasses SDK"},"display":{"binocular_resolution":"3840×1080","color_gamut":"129% sRGB","contrast_ratio":"50,000:1","display_technology":"Micro-OLED","electrochromic_dimming":"Yes; electrochromic transmittance about 3–40%, haze <3%, ~0.3 s","fov_deg":"43","ipd_mm":"57.5–69.5","myopia_adjustment_d":"0 to -5D","ocular_mode":"Binocular","panel_or_projector_brightness":"1800","ppd":"55","refresh_rate_hz":"60","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"Yes","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'One', 'display_ar', 'Display AR/XR glasses', 'Legacy / current support') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('viture-one-lite', 'viture', 'VITURE', 'VITURE One Lite', 'VITURE One Lite 是更低门槛的显示眼镜版本，保留大多数 One 系列核心体验，但把连接改成标准 USB-C，并取消电致变色镜片。', '它更适合把 VITURE 生态当作入门方案来理解：保留大屏体验和 120Hz Full HD 虚拟屏，但减少了一些更精致的硬件特性。', 'VITURE 面向入门用户的显示眼镜。', '2024', '在售', '显示眼镜', NULL, '{"imageUrl":null,"imageAlt":"VITURE One Lite 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'VITURE One Lite 产品视觉', NULL, 'https://www.viture.com/blog/2024-in-review-vitures-greatest-year-yet', NULL, 'display_glasses', '显示眼镜', 'VITURE 面向入门用户的显示眼镜。', '["预算更敏感","想体验 VITURE 生态","需要标准 USB‑C 连接"]'::jsonb, '["想要完整 One 系列特性","需要电致变色镜片","需要更高端影音体验"]'::jsonb, '["部分高级硬件特性被精简。","仍然是外接显示眼镜，不是独立系统。"]'::jsonb, '[{"field":"audio.speakers","label":"Speakers","value":"Built-in spatial/open-ear speakers"},{"field":"basic.prescription_support","label":"Prescription Support","value":"Supported via prescription frame / built-in diopter adjustment"},{"field":"basic.weight_g","label":"Weight G","value":"76"},{"field":"connectivity.android","label":"Android","value":"Supported on compatible video-output devices"},{"field":"connectivity.hdmi","label":"Hdmi","value":"Supported via adapter/dock"}]'::jsonb, '{"audio":{"speakers":"Built-in spatial/open-ear speakers"},"basic":{"prescription_support":"Supported via prescription frame / built-in diopter adjustment","weight_g":"76"},"connectivity":{"android":"Supported on compatible video-output devices","hdmi":"Supported via adapter/dock","ios":"Supported with appropriate VITURE adapter/accessory","macos":"Supported","nintendo_switch":"Supported via appropriate accessory","playstation":"Supported via HDMI accessory","usb_c_dp":"Supported (connector/cable architecture varies by model)","windows":"Supported","xbox":"Supported via HDMI accessory"},"developer":{"sdk":"VITURE XR Glasses SDK","spatial_api":"3DoF head tracking supported by official VITURE XR Glasses SDK"},"display":{"binocular_resolution":"3840×1080","color_gamut":"129% sRGB","contrast_ratio":"50,000:1","display_technology":"Micro-OLED","electrochromic_dimming":"No; fixed transmittance about 23%","fov_deg":"43","ipd_mm":"57.5–69.5","myopia_adjustment_d":"0 to -5D","ocular_mode":"Binocular","panel_or_projector_brightness":"1800","ppd":"55","refresh_rate_hz":"60","resolution_per_eye":"1920×1080"},"tracking":{"environment_sensors":"IMU","eye_tracking":"No","hand_tracking":"No","native_3dof":"Yes","native_6dof":"No","slam":"No"}}'::jsonb, 'published', 'One Lite', 'display_ar', 'Display AR/XR glasses', 'Legacy / current support') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('inmo-air-2', 'inmo', 'INMO', 'INMO Air 2', 'INMO Air 2 是一款更偏轻量 AR 和提示式信息体验的设备，定位不是外接观影大屏，而是把基础应用和信息提示放到眼前。', '它更接近独立轻量 AR 路线，适合观察日常佩戴、控制器交互和低干扰信息呈现。', '轻量 AR 与提示式信息体验优先。', '2023', NULL, 'AR 眼镜', '资料待补充', '{"imageUrl":null,"imageAlt":"INMO Air 2 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'INMO Air 2 产品视觉', NULL, 'https://www.inmoxr.com/pages/inmo-air2', NULL, 'ar_glasses', 'AR 眼镜', '强调轻量 AR，而不是纯显示大屏。', '["研究轻量 AR","观察独立系统边界","提示式信息呈现"]'::jsonb, '["追求沉浸大屏","把它当成熟娱乐设备","需要完整 PC 级计算能力"]'::jsonb, '["公开硬件细节仍有限。","显示与平台定位比绝对规格更重要。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"INMO GPT / OpenAI integration"},{"field":"ai_features.navigation","label":"Navigation","value":"Yes"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"Yes"},{"field":"ai_features.transcription","label":"Transcription","value":"Meeting features supported"},{"field":"ai_features.translation","label":"Translation","value":"Yes"}]'::jsonb, '{"ai_features":{"ai_assistant":"INMO GPT / OpenAI integration","navigation":"Yes","teleprompter":"Yes","transcription":"Meeting features supported","translation":"Yes","vision_ai":"Yes"},"audio":{"microphones":"2 microphones","speakers":"2 speakers"},"basic":{"material":"PC+ABS (official regulatory manual)","prescription_support":"Supported","weight_g":"99"},"battery":{"battery_capacity_mah":"500"},"camera":{"camera_mp":"8 MP (medium-confidence secondary corroboration)","camera_present":"Yes","secondary_spatial_camera":"Second front-facing camera / tracking camera present","video_resolution_fps":"1080p @ 30 fps (medium-confidence secondary corroboration)"},"compute":{"cpu":"Quad-core up to 1.8 GHz","os":"IMOS 2.0 (Android-based; official regulatory manual lists Android 9 base)","ram":"2 GB","soc":"Unisoc / Ziguang Zhanrui W517-class AI chip","storage":"32 GB"},"connectivity":{"android":"Android-based standalone system with companion connectivity","bluetooth":"Bluetooth 5.0","usb":"Pogo-pin / proprietary charging-data connection","wifi":"2.4 GHz / 5 GHz Wi-Fi"},"developer":{"spatial_api":"SLAM capabilities"},"display":{"color":"Full color","contrast_ratio":"20,000:1","display_present":"Yes","display_technology":"Binocular full-color Micro-OLED","fov_deg":"26","ocular_mode":"Binocular","optical_system":"Reflective waveguide","optical_transmittance":"Up to 85%","refresh_rate_hz":"60","resolution_per_eye":"640×400"},"privacy":{"physical_camera_cover":"No"},"tracking":{"sensors":"Accelerometer, gyroscope, magnetometer, global-shutter tracking sensor","slam":"Yes"}}'::jsonb, 'published', 'Air 2', 'ai_hud', 'AI/HUD smart glasses', 'Legacy / current support varies by region') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('inmo-go3', 'inmo', 'INMO', 'INMO GO3', 'INMO GO3 更偏实时字幕、翻译和全天佩戴的 AI 眼镜路线，采用轻量双目 Micro‑LED + 波导显示，而不是大屏观影。', '它把重点放在低干扰提示、语言沟通和随身助理场景，系统和交互也更像轻量终端，而不是娱乐大屏。', '翻译和随身提示导向的 AI 眼镜。', '2025', '在售', 'AI 眼镜', NULL, '{"imageUrl":null,"imageAlt":"INMO GO3 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'INMO GO3 产品视觉', NULL, 'https://www.inmoxr.com/pages/inmo-go3-ai-glasses', 'https://www.inmoxr.com/pages/inmo-go3-ai-glasses', 'ai_glasses', 'AI 眼镜', '翻译和随身提示导向的 AI 眼镜。', '["实时字幕与翻译","低干扰提示","全天候轻量佩戴"]'::jsonb, '["期待沉浸大屏","主要看电影打游戏","需要开放开发平台"]'::jsonb, '["不是影院型显示眼镜。","主要价值在提示和翻译，不在大屏娱乐。"]'::jsonb, '[{"field":"ai_features.navigation","label":"Navigation","value":"HERE Maps"},{"field":"ai_features.other_features","label":"Other Features","value":"Touch, button, ring, app and voice controls"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"Yes"},{"field":"ai_features.transcription","label":"Transcription","value":"Meeting / transcription features"},{"field":"ai_features.translation","label":"Translation","value":"98 target languages online; 9 offline"}]'::jsonb, '{"ai_features":{"navigation":"HERE Maps","other_features":"Touch, button, ring, app and voice controls","teleprompter":"Yes","transcription":"Meeting / transcription features","translation":"98 target languages online; 9 offline","vision_ai":"Yes"},"audio":{"microphones":"4 microphones","speakers":"2 speakers"},"basic":{"material":"Aluminum alloy + PA","prescription_support":"Supported","weight_g":"58"},"battery":{"battery_capacity_mah":"270 × 2 swappable batteries","charging_case":"1300 mAh; approximately 3–4 full charges","mode_specific_runtime":"Translation up to 3 h; teleprompter up to 3.3 h; music/calls up to 4.5 h","official_typical_runtime":"Up to 8+ h standby"},"camera":{"camera_fov_deg":"120","camera_mp":"8 MP","camera_present":"Yes","secondary_spatial_camera":"No","stabilization":"EIS","video_resolution_fps":"720p @ 30 fps"},"compute":{"cpu":"Dual-core CPU","os":"RTOS","ram":"256 MB","storage":"64 GB"},"connectivity":{"android":"Supported","gps":"Navigation via HERE Maps / phone ecosystem","ios":"Supported"},"display":{"color":"Green monochrome","display_present":"Yes","display_technology":"Green MicroLED","eye_brightness":"1500","fov_deg":"30","ocular_mode":"Binocular","optical_system":"Binocular diffractive waveguide","resolution_per_eye":"640×480"},"privacy":{"physical_camera_cover":"Yes"}}'::jsonb, 'published', 'GO3', 'ai_hud', 'AI/HUD smart glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('ray-ban-meta', 'meta', 'META × RAY-BAN', 'Ray-Ban Meta', 'Ray-Ban Meta 是一款无显示 AI 眼镜，重点是第一视角拍摄、音频和语音助理，而不是画面显示。它更接近日常穿戴设备，不是大屏产品。', '这条路线说明智能眼镜并不一定从显示开始，而是先从拍摄、音频和 AI 助手切入高频日常使用。', '无显示、重拍摄和语音入口的 AI 眼镜。', '2023', '在售', 'AI 眼镜', NULL, '{"imageUrl":null,"imageAlt":"Ray-Ban Meta 产品视觉","imageBackground":"dark","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Ray-Ban Meta 产品视觉', NULL, 'https://www.ray-ban.com/usa/ray-ban-meta-ai-glasses', NULL, 'ai_glasses', 'AI 眼镜', '无显示、重拍摄和语音入口。', '["第一视角拍摄","音频交互","轻量 AI 穿戴研究"]'::jsonb, '["期待显示大屏","想做波导或空间界面开发","需要完整独立计算"]'::jsonb, '["没有显示模组。","很多 AI 能力依赖联网和手机配合。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"Meta AI"},{"field":"ai_features.navigation","label":"Navigation","value":"No visual HUD navigation; voice/location assistance availability varies"},{"field":"ai_features.notifications","label":"Notifications","value":"Audio/voice notifications through companion ecosystem"},{"field":"ai_features.other_features","label":"Other Features","value":"Live AI availability varies by market"},{"field":"ai_features.translation","label":"Translation","value":"Yes, market/language availability varies"}]'::jsonb, '{"ai_features":{"ai_assistant":"Meta AI","navigation":"No visual HUD navigation; voice/location assistance availability varies","notifications":"Audio/voice notifications through companion ecosystem","other_features":"Live AI availability varies by market","translation":"Yes, market/language availability varies","vision_ai":"Yes"},"audio":{"microphones":"Custom 5-microphone array (Wayfarer Gen 2 SKU; microphone count can vary by Gen 2 style/SKU)","speakers":"2 open-ear speakers"},"basic":{"dimensions_mm":"Varies by frame/SKU","material":"Varies by frame/SKU","prescription_support":"Supported on eligible frames","weight_g":"~53 (varies by frame/SKU)"},"battery":{"charging_case":"Up to +48 h claimed","mode_specific_runtime":"Continuous audio up to ~5 h; calls up to ~5.5 h (official SKU-dependent figures)","official_typical_runtime":"Up to 8 h claimed"},"camera":{"camera_mp":"12 MP ultrawide","camera_present":"Yes","photo_resolution":"3024×4032","secondary_spatial_camera":"No","video_resolution_fps":"Up to 3K @ 30 fps; 1080p modes available up to 60 fps depending SKU/mode"},"compute":{"os":"Embedded Meta smart-glasses firmware / no public standalone OS name","soc":"Qualcomm Snapdragon AR1 Gen 1","storage":"32 GB"},"connectivity":{"android":"Android 10 minimum on current Wayfarer Gen 2 SKU","bluetooth":"Bluetooth 5.3","gps":"Phone-assisted","ios":"iOS 14.4 minimum on current Wayfarer Gen 2 SKU","usb":"Charging case / accessory-based charging","wifi":"Wi-Fi 6E (current Wayfarer Gen 2 SKU; some other Gen 2 styles/pages list Wi-Fi 6)"},"developer":{"firmware_openness":"Closed consumer firmware"},"display":{"display_present":"No"},"privacy":{"camera_indicator":"Yes; external capture LED","physical_camera_cover":"No","privacy_notes":"IPX4 water resistance is listed for current product."}}'::jsonb, 'published', 'Gen 2', 'ai_hud', 'AI/HUD smart glasses', 'Current') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('brilliant-labs-frame', 'brilliant-labs', 'Brilliant Labs', 'Brilliant Labs Frame', 'Brilliant Labs Frame 是一款偏实验和开发的 AI 眼镜，用于快速原型、接口实验和轻量穿戴交互，不是面向大众娱乐消费的完整平台。', '它更像开放实验设备，而不是成熟消费眼镜。重点在 Noa 平台、官方文档和开发边界。', '开放实验和快速原型优先的开发设备。', '2024', NULL, '开发设备', '开发设备', '{"imageUrl":null,"imageAlt":"Brilliant Labs Frame 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"frame"}'::jsonb, NULL, NULL, 'Brilliant Labs Frame 产品视觉', NULL, 'https://brilliant.xyz/products/frame', NULL, 'developer_device', '开发设备', '强调开放实验，而不是消费级完成度。', '["开发探索","原型验证","研究开放硬件方向"]'::jsonb, '["直接消费使用","期待成熟娱乐体验","需要完整双眼显示"]'::jsonb, '["更强调实验性而非消费完成度。","单眼小显示不适合观影。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"Noa / developer-configurable AI experiences"},{"field":"ai_features.navigation","label":"Navigation","value":"App/developer dependent"},{"field":"ai_features.notifications","label":"Notifications","value":"App/developer dependent"},{"field":"ai_features.other_features","label":"Other Features","value":"Highly programmable developer platform"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"App/developer dependent"}]'::jsonb, '{"ai_features":{"ai_assistant":"Noa / developer-configurable AI experiences","navigation":"App/developer dependent","notifications":"App/developer dependent","other_features":"Highly programmable developer platform","teleprompter":"App/developer dependent","transcription":"App/developer dependent","translation":"App/developer dependent","vision_ai":"Supported through camera + connected/cloud AI workflows"},"audio":{"audio_notes":"No speaker is listed in the official hardware manual.","microphones":"1 × ICS-41351 microphone"},"basic":{"prescription_support":"Optional prescription lenses"},"battery":{"battery_capacity_mah":"210 total (2 × 105 mAh)","charging_case":"Charging cradle 140 mAh","charging_time":"Frame + charging cradle approximately 2 h"},"camera":{"camera_present":"Yes","camera_sensor":"OV09734","photo_resolution":"Raw sensor 1280×720; API capture up to 720×720 crop","secondary_spatial_camera":"No","video_resolution_fps":"720p-class low-power camera; exact consumer video mode Not disclosed"},"compute":{"cpu":"Cortex-M4F @ 64 MHz","os":"Lua-based / open customizable firmware","ram":"256 KB","soc":"Nordic nRF52840 MCU + Lattice CrossLink-NX FPGA","storage":"1 MB MCU flash"},"connectivity":{"android":"Companion/app dependent","bluetooth":"Bluetooth 5.3","ios":"Companion/app dependent","pc_compatibility":"Developer tools via SDK/workflow","usb":"Charging cradle interface"},"developer":{"camera_api":"Yes","firmware_openness":"Open-source / customizable","sdk":"Frame SDK","sideload":"Developer-custom firmware/apps supported","spatial_api":"Motion sensor API; no 6DoF spatial mapping"},"display":{"color":"255 possible colors; max 16 per frame","display_present":"Yes","display_technology":"0.23-inch color micro-OLED","fov_deg":"20","ocular_mode":"Monocular display architecture","resolution_per_eye":"640×400"},"privacy":{"physical_camera_cover":"No"},"tracking":{"eye_tracking":"No","hand_tracking":"No","native_6dof":"No","sensors":"3-axis accelerometer + 3-axis e-compass","slam":"No"}}'::jsonb, 'published', 'Frame', 'ai_hud', 'AI/HUD smart glasses', 'Current / developer-oriented') ON CONFLICT DO NOTHING;
INSERT INTO public.devices (slug, brand_key, brand_name, name, short_description, long_description, positioning, release_year, availability, type_label, status_label, media, product_image_url, official_image_url, image_alt, product_url, official_product_url, buy_url, category, route_label, route_description, best_for, not_ideal_for, key_limitations, key_specs, full_specs, publication_status, generation, schema_type, device_type, status) VALUES ('even-realities-g1', 'even-realities', 'Even Realities', 'Even Realities G1', 'Even Realities G1 是一款偏低干扰信息提示的智能眼镜，核心是通知、轻量信息和日常佩戴，而不是沉浸式 AR 大屏。', '它更适合被看作提示型智能眼镜：重点是把短信息放到视线里，而不是提供完整的大屏体验。', '低干扰信息提示优先，不走大屏路线。', NULL, NULL, 'AI 眼镜', NULL, '{"imageUrl":null,"imageAlt":"Even Realities G1 产品视觉","imageBackground":"light","imageFit":"contain","hasConfirmedImage":false,"placeholderType":"glasses"}'::jsonb, NULL, NULL, 'Even Realities G1 产品视觉', NULL, 'https://www.evenrealities.com/en-FI/g1', NULL, 'ai_glasses', 'AI 眼镜', '更偏提示型智能眼镜，不走大屏路线。', '["通知与轻量信息","低干扰佩戴","提示式眼镜观察"]'::jsonb, '["期待沉浸式显示","需要开放平台","把它当观影设备"]'::jsonb, '["公开硬件细节相对有限。","定位更偏提示，而不是完整 AR。"]'::jsonb, '[{"field":"ai_features.ai_assistant","label":"Ai Assistant","value":"Even AI"},{"field":"ai_features.navigation","label":"Navigation","value":"Yes"},{"field":"ai_features.notifications","label":"Notifications","value":"Yes"},{"field":"ai_features.other_features","label":"Other Features","value":"QuickNote; Dashboard"},{"field":"ai_features.teleprompter","label":"Teleprompter","value":"Yes"}]'::jsonb, '{"ai_features":{"ai_assistant":"Even AI","navigation":"Yes","notifications":"Yes","other_features":"QuickNote; Dashboard","teleprompter":"Yes","transcription":"Yes","translation":"Yes"},"audio":{"audio_notes":"No speaker/audio output is listed in the official hardware specifications.","microphones":"2 microphones"},"basic":{"dimensions_mm":"Hinge-to-hinge 134 mm; lens height 41.8 mm; bridge 23 mm; temple 139.2 mm","prescription_support":"Supported"},"battery":{"charging_case":"Approximately 2.5 additional charges","charging_time":"Approximately 2–3 h","official_typical_runtime":"Up to 1.5 days"},"camera":{"camera_present":"No"},"compute":{"os":"Companion-linked embedded firmware"},"connectivity":{"android":"Supported","bluetooth":"BLE 5.2","gps":"Phone-assisted navigation","ios":"Supported"},"developer":{"firmware_openness":"Closed consumer firmware"},"display":{"color":"Green monochrome","display_present":"Yes","display_technology":"MicroLED","eye_brightness":"1000","fov_deg":"25","ocular_mode":"Binocular","optical_system":"Waveguide","optical_transmittance":"98%","refresh_rate_hz":"20","resolution_per_eye":"640×200"},"privacy":{"privacy_notes":"Camera-free design; official materials describe splash/light-rain resistance but do not consistently provide a numeric IP rating."},"tracking":{"sensors":"Auto-brightness / ambient sensing; other sensors Not disclosed"}}'::jsonb, 'published', 'G1', 'ai_hud', 'AI/HUD smart glasses', 'Current') ON CONFLICT DO NOTHING;
